def reserve(stock: int, requested: int):
    if not isinstance(stock, int) or not isinstance(requested, int):
        raise TypeError('inputs must be integers')
    if requested < 0:
        raise ValueError('requested must be non-negative')
    accepted = requested <= stock
    if accepted:
        stock -= requested
    return {'accepted': accepted, 'remaining': stock}
